INSERT INTO `reviews` (`id`, `product_id`, `variant_id`, `user_id`, `order_item_id`, `rating`, `title`, `content`, `image_urls`, `is_verified_purchase`, `is_approved`, `helpful_count`, `reply`, `replied_at`, `created_at`, `updated_at`) VALUES
(1, 1, 1, 1, 1, 5, 'Sản phẩm xuất sắc!', 'Galaxy S25 Ultra hoàn toàn xứng đáng với số tiền bỏ ra. Camera siêu đỉnh, pin trâu, màn hình đẹp lung linh. Rất hài lòng!', '[\"reviews/1/img1.jpg\"]', 1, 1, 45, 'Cảm ơn bạn đã tin dùng TechZone!', '2026-02-10 09:00:00', '2026-02-06 20:00:00', '2026-02-06 20:00:00'),
(2, 2, 3, 2, 2, 5, 'iPhone 16 Pro Max tuyệt vời', 'Máy mượt mà, camera đẹp không tưởng, pin cải thiện rõ rệt so với đời trước. Đóng gói cẩn thận, giao nhanh.', NULL, 1, 1, 38, NULL, NULL, '2026-02-07 21:00:00', '2026-02-07 21:00:00'),
(3, 5, 7, 3, 3, 5, 'Dell XPS 15 - Laptop đẳng cấp', 'Màn hình OLED cực đẹp, hiệu năng mạnh mẽ, build quality tốt. Pin khoảng 6-7 tiếng dùng thực tế. Hoàn toàn xứng đáng.', '[\"reviews/3/img1.jpg\",\"reviews/3/img2.jpg\"]', 1, 1, 28, 'Cảm ơn bạn đã review chi tiết!', '2026-02-12 14:00:00', '2026-02-09 19:00:00', '2026-02-09 19:00:00'),
(4, 13, NULL, 4, 4, 4, 'Váy đẹp nhưng giao chậm', 'Chất vải mềm mịn, màu sắc đúng như hình, kiểu dáng duyên dáng. Tuy nhiên giao hàng hơi lâu, mất 4 ngày mới nhận được.', NULL, 1, 1, 12, 'Chúng tôi sẽ cải thiện tốc độ giao hàng!', '2026-02-15 10:00:00', '2026-02-09 00:00:00', '2026-02-09 00:00:00'),
(5, 14, 16, 5, 5, 5, 'Nike Pegasus 41 - Giày chạy hoàn hảo', 'Đệm êm tuyệt vời, fit chân đúng size, nhẹ và thoáng khí. Chạy 10km thấy rõ sự khác biệt. Sẽ mua thêm!', '[\"reviews/5/img1.jpg\"]', 1, 1, 67, NULL, NULL, '2026-02-10 20:00:00', '2026-02-10 20:00:00'),
(6, 10, NULL, 6, 6, 5, 'Seiko Presage đẳng cấp', 'Đồng hồ đẹp tinh tế, kính sapphire không bị trầy dù đeo hàng ngày. Cơ chuyển trơn tru, dây da thật rất bền.', NULL, 1, 1, 22, NULL, NULL, '2026-02-11 23:00:00', '2026-02-11 23:00:00'),
(7, 31, NULL, 1, NULL, 1, 'Không chống nước', 'Sản phẩm ok đấy mà ngâm nước mỗi tí đã hỏng', NULL, 0, 1, 0, 'Xin lỗi vì sự bất tiện này! Chúng tôi sẽ xử lý và liên hệ lại sớm nhất.', '2026-05-05 13:40:52', '2026-05-04 23:39:10', '2026-05-04 23:40:52'),
(8, 31, NULL, 1, NULL, 5, 'sdsdfds', 'ưdwe', NULL, 0, 1, 0, 'Cảm ơn bạn đã phản hồi! Chúng tôi rất trân trọng ý kiến của bạn.', '2026-05-07 19:15:38', '2026-05-04 23:43:28', '2026-05-07 05:15:38'),
(9, 25, NULL, 1, NULL, 5, 'OK', 'Sản phẩm tốt', NULL, 0, 1, 0, NULL, NULL, '2026-05-07 23:11:37', '2026-05-07 23:11:37'),
